import * as maplibregl from './vendor/maplibre-gl/maplibre-gl.mjs';

const map = new maplibregl.Map({
  container: 'map',
  center: [-100, 30],
  zoom: 1.6,
  style: {
    version: 8,
    projection: {type: 'globe'},
    sources: {},
    layers: [{id: 'bg', type: 'background', paint: {'background-color': '#0a2540'}}]
  }
});

// switch at any time
map.setProjection({type: 'mercator'});

import {GlobeMap, ShapeModel} from './src/maps.js';

// GlobeMap - round worlds on MapLibre. Three today:
const map = new GlobeMap({container: 'map', body: 'earth'});
await map.ready;
map.bodies;                 // ['earth', 'moon', 'mars']  - the authoritative list
map.basesFor('earth');      // ['base-open', 'bluemarble', 's2', 'viirs']
map.basesFor('moon');       // ['moon-wac']
map.basesFor('mars');       // ['mars-viking', 'mars-mola']
map.overlaysFor('earth');   // ['borders', 'hillshade', 'terrain3d', 'osm', 'quakes']
await map.setBody('mars', {base: 'mars-mola'});
// setBody('phobos') -> Error: Unknown body - irregular worlds use ShapeModel:

// ShapeModel - irregular worlds from any NASA glTF (.glb). Bundled under data/models/:
new ShapeModel({container: 'view', model: 'data/models/phobos.glb',   body: 'phobos'});
new ShapeModel({container: 'view', model: 'data/models/ganymede.glb', body: 'ganymede'});
// opts.body ties the mesh to the astronomy engine (sky, Sun, parent orbit):
//   earth . moon . mars . phobos . ganymede . jupiter

import {ShapeModel} from './src/maps.js';

// Phobos is ~27x22x18 km and lumpy: map onto its real shape, not a sphere.
const model = new ShapeModel({
  container: 'view',
  model: 'data/models/phobos.glb',   // NASA 3D Resources glTF (.glb)
  radiusKm: [13.0, 11.4, 9.1],       // triaxial, for the readout
  graticule: true,
  lonDir: -1,                        // Phobos is measured west-positive
  features: [{name: 'Stickney', lon: 49, lat: 1}]
});
await model.ready;
model.on('select', (f) => console.log(f.name, f.lon, f.lat));
model.flyTo({lon: 49, lat: 1});      // swing round to the giant crater

map.addSource('dem', {
  type: 'raster-dem',
  tiles: ['https://tiles.mapterhorn.com/{z}/{x}/{y}.webp'],
  tileSize: 512,
  encoding: 'terrarium',
  maxzoom: 12
});
map.addLayer({id: 'hillshade', type: 'hillshade', source: 'dem'});
map.setTerrain({source: 'dem', exaggeration: 1.5});

map.setSky({
  'atmosphere-blend': ['interpolate', ['linear'], ['zoom'], 0, 1, 5, 1, 7, 0]
});

// Real, time-aware sky; toggle any layer.
const sky = map.addStarfield({
  time: '2026-07-01T00:00Z',
  milkyWay: true, constellations: true,
  planets: true, sun: true, moon: true,
  grid: false, ecliptic: false, magLimit: 6
});
sky.setTime('2026-12-21T00:00Z');   // advance the whole sky

// Reachable worlds show up as clickable hotspots in the sky.
// Clicking Mars (from Earth) flies there and swaps the model:
map.on('travel', (body) => console.log('flying to', body));
await map.travelTo('mars');          // or let the user click the hotspot

// real day/night shading on the globe
map.addTerminator();

map.addSource('ne', {type: 'geojson', data: 'data/ne_110m_admin_0_countries.geojson'});
map.addLayer({id: 'land', type: 'fill', source: 'ne', paint: {'fill-color': '#1c2b33'}});
map.addLayer({id: 'borders', type: 'line', source: 'ne', paint: {'line-color': '#9fb4c4'}});

map.addSource('s2', {
  type: 'raster',
  tiles: ['https://tiles.maps.eox.at/wmts/1.0.0/s2cloudless_3857/default/g/{z}/{y}/{x}.jpg'],
  tileSize: 256,
  maxzoom: 13,
  attribution: 'Sentinel-2 cloudless by EOX IT Services GmbH (contains modified Copernicus Sentinel data 2016)'
});
map.addLayer({id: 's2', type: 'raster', source: 's2'});

map.addSource('osm', {type: 'vector', url: 'https://tiles.openfreemap.org/planet'});
map.addLayer({
  id: 'roads', type: 'line', source: 'osm', 'source-layer': 'transportation',
  metadata: {'gv:store': 'quarantine'},   // paid-tier builds strip these
  paint: {'line-color': '#c9d3dc'}
});

const url = manifest['gibs-viirs'].url;   // contains {date}

function setDate(day) {              // '2026-11-08'
  map.getSource('viirs').setTiles([url.replace('{date}', day)]);
}

map.addSource('quakes', {
  type: 'geojson',
  data: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_day.geojson'
});
map.addLayer({
  id: 'quakes', type: 'circle', source: 'quakes',
  paint: {
    'circle-radius': ['interpolate', ['linear'], ['get', 'mag'], 2.5, 3, 7, 18],
    'circle-color': ['interpolate', ['linear'], ['get', 'mag'], 2.5, '#ffd166', 7, '#e2675f']
  }
});

// Renderer is live; the DEFAULT field is illustrative, not a forecast.
// Pass field(lng, lat) => [u, v] (deg/sec) to drive from real data.
const flow = map.addParticles({count: 2000});

flow.stop();   // or map.removeParticles()

const steps = map.timesteps('viirs', {days: 7});   // ISO days available
map.setLayerTime('viirs', steps.at(-1));

// or animate it
const player = map.playTimesteps('viirs', {days: 7, intervalMs: 900});
player.stop();

const res = await fetch(entry.probe, {mode: 'cors', cache: 'no-store'});
probes[entry.id] = {
  state: res.ok ? 'ok' : 'fail',
  status: res.status,
  type: res.headers.get('content-type')
};
// a layer whose probe is not 'ok' cannot be enabled

new PerformanceObserver((list) => {
  for (const r of list.getEntries()) count(new URL(r.name).host, r.duration);
}).observe({type: 'resource', buffered: true});

// Read entirely in the browser. Nothing is uploaded.
// addUserLayer routes by type: GeoJSON / KML / GPX, {z}/{x}/{y} raster, PMTiles, GeoTIFF.
const layer = await map.addUserLayer(fileOrUrl);
console.log(layer.kind, layer.license);   // 'geojson' | 'pmtiles' | 'geotiff' ...

// Or call a format directly:
await map.addPMTiles('https://example.com/basemap.pmtiles');   // vector or raster, HTTP range
const cog = await map.addGeoTIFF(file);                        // .tif / .tiff / COG
console.log(cog.crs, cog.size);                                // 'EPSG:4326'  [width, height]

map.removeUserLayer(layer.id);

// Paint an imaginary planet on the template, then wrap it on the globe.
const png = GlobeMap.sphereTemplate({ width: 2048 });   // equirectangular guide, 2:1

// ...paint it, export it, then:
await map.addUserWorld(fileOrUrl);   // File/Blob, image URL, or ImageBitmap
map.removeUserWorld();

const draw = map.draw({mode: 'polygon'});   // 'point' | 'linestring' | 'polygon'

draw.on('finish', (feature) => {
  console.log(feature.properties);   // { mode, length_km, area_km2 }
  save(feature);
});

draw.clear();   // drop everything drawn
draw.stop();    // end the session

const hits = map.search('United', {limit: 8});   // self-hosted, no request leaves the page
console.log(hits[0]);   // { name, center: [lng, lat], bbox }

map.flyToPlace(hits[0]);

import {GlobeMap} from './src/maps.js';

const map = new GlobeMap({
  container: 'map',
  body: 'earth',            // 'earth' | 'moon' | 'mars'
  base: 'base-open',        // a base layer for that body
  projection: 'globe'       // 'globe' | 'mercator'
});

// every source announces itself as its probe runs
map.on('probe', (s) => console.log(s.id, s.state, s.commercial));

await map.ready;            // manifest loaded, probes run, globe drawn

// switch worlds at any time
await map.setBody('mars', {base: 'mars-viking'});

// add a live science layer; rejects if its probe did not pass
await map.addLayer('quakes');
